{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In a rat oral study, chlorogenic acid, rutin, and hyperoside were detected in brain, providing direct evidence that flavonoid glycosides can cross the BBB despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Hydroxysafflor yellow A, a large polar C-glycoside, reached 1026 ng/g in rat brain in a tissue distribution study, showing that multiple sugar groups and high polarity do not preclude meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cyanidin 3-glucoside, a charged anthocyanin glycoside, was detected in human brain and vascular endothelium, supporting CNS access for charged glycosylated polyphenols.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a kaempferol glucoside, was detected in rat brain after tissue distribution analysis, directly supporting BBB crossing for flavonoid monoglycosides.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite the query's unfavorable passive diffusion properties as a flavonoid glucuronide, multiple high-transfer flavonoid glycosides and charged glycosides are directly detected in brain after systemic administration, supporting meaningful CNS access for this compound.",
  "evidence_gaps": [
    "No direct baicalin-specific brain, plasma, or CSF concentration measurement is available in the provided evidence.",
    "The possible contribution of deglucuronidation to the aglycone baicalein and subsequent brain uptake is not directly quantified.",
    "Efflux transporter liability for the glucuronide is not experimentally measured in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

